public:
    InputReader(std::istream& stream) : sr(stream), seek(0), isDispose(false) {}

    ~InputReader() {
        Dispose(false);
    }

    void Dispose() {
        Dispose(true);
    }

    void Dispose(bool disposing) {
        if (!isDispose) {
            if (disposing) {
