        return buffer[seek++];
    }

    long long NextInt64() {
        return std::stoll(ReadNextToken());
    }

    std::vector<int> ReadArrayOfInt32() {
        return ReadArray<int>([](const std::string& s) { return std::stoi(s); });
    }

    std::vector<long long> ReadArrayOfInt64() {
        return ReadArray<long long>([](const std::string& s) { return std::stoll(s); });
    }

    std::vector<std::string> NextSplitStrings() {
        std::string line = NextString();
        std::vector<std::string> tokens;
        std::istringstream iss(line);
